import {clone} from './core.js';
import {normalizeMirrorSelection} from './mirror-service.js';
export const fabrics={jersey:{name:'Jersey',intensity:16,size:7},fleece:{name:'Frisado',intensity:22,size:10,density:true},waffle:{name:'Waffle',intensity:28,size:12},terry:{name:'Rústico',intensity:24,size:10,density:true},rib:{name:'Textura Rib',intensity:22,size:7},denim:{name:'Denim',intensity:24,size:9},twill:{name:'Gabardina',intensity:22,size:10}};
export const fabricEligible=o=>o.type==='path'&&o.closed;
export function fabricTexture(type,extra={}){if(!fabrics[type])return null;return {type,scale:1,intensity:fabrics[type].intensity,angle:0,density:1,colorMode:'automatic',customColor:'#637080',origin:{x:0,y:0},seed:1,...extra};}
export function assignFabric(p,view,ids,type,{scope='this',...params}={}){const targets=p.liveMirror?normalizeMirrorSelection(p.views[view],ids):ids;for(const o of p.views[view].filter(o=>targets.includes(o.id)&&fabricEligible(o))){if(type==='none')delete o.fabricTexture;else o.fabricTexture=fabricTexture(type,{...o.fabricTexture,...params,type});if(scope==='both'){const other=view==='front'?'back':'front',link=p.garment.links.find(l=>l[view]===o.id),peer=p.views[other].find(x=>x.id===link?.[other]);if(peer&&fabricEligible(peer)){if(type==='none')delete peer.fabricTexture;else peer.fabricTexture=clone(o.fabricTexture);}}}}
export function textureTone(fill,t){const h=/^#[a-f\d]{6}$/i.test(fill||'')?fill:'#808080',rgb=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),light=rgb.reduce((s,v)=>s+v,0)/3<140;if(t.colorMode==='custom'&&/^#[a-f\d]{6}$/i.test(t.customColor))return t.customColor;const up=t.colorMode==='light'||t.colorMode==='automatic'&&light,base=up?255:0;return '#'+rgb.map(v=>Math.round(v+(base-v)*.38).toString(16).padStart(2,'0')).join('');}

export function fabricMarks(type,seed=1){
 if(type==='jersey')return 'M 0 0 C 0 2 1 3 3 4 C 5 3 6 2 6 0 M 0 4 C 0 6 1 7 3 8 C 5 7 6 6 6 4 M 3 4 L 3 0 M 3 8 L 3 4';
 if(type==='fleece'){let state=Number(seed)||1;const random=()=>{state=(state*1664525+1013904223)>>>0;return state/4294967296;};return Array.from({length:22},()=>{const x=random()*10,y=random()*10,dx=(random()-.5)*2.8,dy=(random()-.5)*2.8;return `M ${x.toFixed(2)} ${y.toFixed(2)} q ${(dx*.7).toFixed(2)} ${(dy*.3).toFixed(2)} ${dx.toFixed(2)} ${dy.toFixed(2)}`;}).join(' ');}
 if(type==='waffle')return 'M 0 0 H 12 V 12 H 0 Z M 2 2 H 10 V 10 H 2 Z M 3 3 H 9 V 9 H 3 Z M 0 0 L 3 3 M 12 0 L 9 3 M 12 12 L 9 9 M 0 12 L 3 9 M 4 5 H 8 M 4 7 H 8';
 if(type==='terry')return 'M 1 5 C -1 0 5 0 4 5 C 3 9 0 9 1 5 M 6 10 C 4 5 10 5 9 10 C 8 14 5 14 6 10 M 6 0 C 8 4 10 4 9 0 M 2 2 Q 4 4 2 7 M 7 7 Q 9 9 7 12';
 if(type==='rib')return 'M 0 0 V 8 M 2 0 V 8 M 4 0 C 4 2 5 2 5 4 C 5 6 4 6 4 8 M 7 0 C 7 2 6 2 6 4 C 6 6 7 6 7 8 M 2 0 L 4 2 M 2 4 L 4 6';
 if(type==='denim')return 'M -3 3 L 3 -3 M 0 9 L 9 0 M 6 12 L 12 6 M 0 3 L 2 1 M 3 6 L 5 4 M 6 9 L 8 7 M 1 0 V 9 M 4 0 V 9 M 7 0 V 9 M 0 2 H 9 M 0 5 H 9 M 0 8 H 9';
 return 'M -2 2 L 2 -2 M 0 10 L 10 0 M 8 12 L 12 8 M -1 5 L 5 -1 M 2 12 L 12 2 M 0 1 L 1 0 M 0 6 L 6 0 M 4 10 L 10 4';
}
export function fabricPattern(o){const t=o.fabricTexture,f=fabrics[t?.type];if(!f||t.enabled===false)return '';const id='fabric-'+o.id,cell={jersey:[6,8],fleece:[10,10],waffle:[12,12],terry:[10,12],rib:[8,8],denim:[9,9],twill:[10,10]}[t.type],scale=Math.max(.15,Math.min(8,t.scale||1))/Math.max(.3,Math.min(3,t.density||1));return `<pattern id="${id}" data-fabric-type="${t.type}" patternUnits="userSpaceOnUse" x="${t.origin?.x||0}" y="${t.origin?.y||0}" width="${cell[0]*scale}" height="${cell[1]*scale}" patternTransform="translate(${o.matrix?.[4]||0} ${o.matrix?.[5]||0}) rotate(${(Number(t.angle)||0)+Math.atan2(o.matrix?.[1]||0,o.matrix?.[0]??1)*180/Math.PI})"><g transform="scale(${scale})" fill="none" stroke="${textureTone(o.fill,t)}" stroke-width="${t.type==='fleece'?.38:t.type==='waffle'?.65:.5}" opacity="${Math.max(0,Math.min(100,t.intensity??f.intensity))/100}"><path d="${fabricMarks(t.type,t.seed)}" stroke-linecap="round" stroke-linejoin="round"/></g></pattern>`;}
export function fabricSwatch(type){const o={id:'swatch-'+type,fill:'#344454',matrix:[1,0,0,1,0,0],fabricTexture:fabricTexture(type,{intensity:65})};return `<svg viewBox="0 0 54 42" aria-hidden="true"><defs>${fabricPattern(o)}</defs><rect width="54" height="42" fill="#344454"/><rect width="54" height="42" fill="url(#fabric-${o.id})"/></svg>`;}
